@property
def pid(self) -> int:
    return self.identity.pid

def force(self) -> None:
    """Signal the original owned group, including an exited leader's members."""
    self.platform.force_group(self.identity)

@property
def retired(self) -> bool:
    """Exact child and its owned group are gone, independent of pipe callbacks."""
    return not self.alive() and (not self.platform.group_members(self.identity))

@abstractmethod
async def wait(self) -> ChildOutcome:
    ...

def _retire_group(self, guard):
    """Run the same guarded physical plan for synchronous and async custody."""
    plan = self._stop_plan(guard)
    while True:
        try:
            delay = next(plan)
        except StopIteration as done:
            return done.value
        time.sleep(delay)

def _release_retired_io(self) -> None:
    """Release owned IO after the identity-bound process group has retired."""
    return None

async def stop(self) -> ChildOutcome:
    if self._stop_task is None:
        self._stop_task = asyncio.create_task(self._stop())
    return await join_retirement(self._stop_task)

def force(self) -> None:
    self.platform.require(self.identity)
    super().force()

async def stop(self) -> ChildOutcome:
    if self._stop_task is None:
        self.require_stop_authority()
    return await super().stop()

@abstractmethod
def reap(self) -> ChildOutcome:
    ...

def stop_sync(self, *, guard=nullcontext) -> ChildOutcome:
    self.require_stop_authority()
    stage = self._retire_group(guard)
    return stage(self.reap())

@contextmanager
def using_attempts(self, attempts):
    """Borrow only this operation's connection; keep the original fence owner."""
    original = self.attempts
    self.attempts = attempts
    try:
        yield
    finally:
        self.attempts = original

async def dispatch(self, event):
    if not tuple(self.handlers_for(event)):
        return event
    return await Coordination.run_async(self.attempts.session.path, partial(self.observe_owned, event))

def observe_owned(self, event, resource):
    """Consume one native observation through joined, worker-owned SQLite."""
    with self.using_attempts(resource.attempts):
        return self.dispatch_sync(event)

@property
def current(self):
    return type(self.attempts.require_fence(self.fence)[1].lifecycle)

@property
def model_started(self):
    return self.current.has_model_context

def advance(self, state):
    if state is self.current:
        return
    result = self.attempts.advance(self.fence, state, expected_pointer_revision=self.pointer_revision, progress=True).value
    self.fence = result.fence

@handles(pi.Response)
def accepted(self, event):
    if event.id == 'native-prompt' and event.success and self.current.starting:
        self.advance(PromptAcceptedAttempt)

@handles(pi.ContextCommitted)
def context(self, event):
    if event.input_id != self.input_id or self.model_started:
        return
    if self.current.starting:
        self.advance(PromptAcceptedAttempt)
    self.advance(ModelRunningAttempt)

@handles(NativePhaseChanged)
def excursion(self, event):
    if self.model_started:
        self.dispatch_sync(event.phase)

@handles(ModelWaitPhase)
def model(self, phase):
    self.advance(ModelRunningAttempt)

@handles(ToolRunningPhase)
def tool(self, phase):
    self.advance(ToolRunningAttempt)

@handles(CompactionPhase)
def compaction(self, phase):
    self.advance(CompactionAttempt)

def finish(self):
    """Native child is reaped and any explicit owner effect has completed."""
    if not self.model_started:
        raise IdentityConflict('native completion lacks model progress')
    self.fence = self.attempts.advance(self.fence, SettlingAttempt, expected_pointer_revision=self.pointer_revision, backend_done=True, process_dead=True, progress=True).value.fence
    return self.fence
